-- Bearer JWT denylist: store jti only (never the raw JWT).
-- id uses IDENTITY for consistency with uuid→int migrated tables.

CREATE TABLE "revoked_access_tokens" (
    "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "jti" UUID NOT NULL,
    "user_id" INTEGER NOT NULL,
    "expires_at" TIMESTAMPTZ(3) NOT NULL,
    "revoked_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "revoked_access_tokens_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "revoked_access_tokens_jti_key" ON "revoked_access_tokens"("jti");

CREATE INDEX "revoked_access_tokens_user_id_idx" ON "revoked_access_tokens"("user_id");

CREATE INDEX "revoked_access_tokens_expires_at_idx" ON "revoked_access_tokens"("expires_at");

ALTER TABLE "revoked_access_tokens"
  ADD CONSTRAINT "revoked_access_tokens_user_id_fkey"
  FOREIGN KEY ("user_id") REFERENCES "users"("id")
  ON DELETE CASCADE ON UPDATE CASCADE;
